const script = `
$ProgressPreference='SilentlyContinue'
$h=@{'User-Agent'='dsh-check';'Accept'='application/vnd.github+json'}
function GetReadme($repo){
  try {
    $r = Invoke-RestMethod -Uri "https://api.github.com/repos/$repo/contents/README.md" -Headers $h -TimeoutSec 30
    $txt = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String(($r.content -replace "\\s","")))
    return $txt
  } catch { return "ERR $repo : $($_.Exception.Message)" }
}
$a = GetReadme 'awesome-dsh-plugin/awesome-dsh-plugin'
"##### AWESOME LIST (3000 chars)"
$a.Substring(0,[Math]::Min(3000,$a.Length))
"##### AWESOME LIST search for free/model sections"
($a -split "\`n" | Select-String -Pattern 'free|免费|model|模型' | Select-Object -First 40) -join "\`n"
`;
const r = await tools.pwsh({ command: script, description: "Fetch awesome-dsh-plugin README", timeoutMs: 120000 });
console.log(r.kind === "foreground" ? (r.stdout.text + r.stderr.text).slice(0, 9000) : JSON.stringify(r).slice(0,400));
